import{_ as a,o as t,c as o,ah as i}from"./chunks/framework.BMM80GXQ.js";const d=JSON.parse('{"title":"Approval Queue","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/ai-agent/approval-queue.md","filePath":"2.0/ai-agent/approval-queue.md","lastUpdated":1775051911000}'),n={name:"2.0/ai-agent/approval-queue.md"};function r(s,e,p,h,l,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="approval-queue" tabindex="-1">Approval Queue <a class="header-anchor" href="#approval-queue" aria-label="Permalink to &quot;Approval Queue&quot;">​</a></h1><p>The Approval Queue is a review mechanism that allows you to inspect and approve (or reject) changes made by the AI Agent before they are applied to your product data. This gives you full control over what the AI Agent modifies in your catalog.</p><h2 id="what-is-the-approval-queue" tabindex="-1">What is the Approval Queue? <a class="header-anchor" href="#what-is-the-approval-queue" aria-label="Permalink to &quot;What is the Approval Queue?&quot;">​</a></h2><p>When the AI Agent performs operations that modify your data, such as updating product descriptions, changing prices, or enriching SEO fields, those changes can be routed through an approval queue instead of being applied immediately. This acts as a safety net, ensuring that no unintended modifications reach your live catalog without your explicit consent.</p><h2 id="configurable-modes" tabindex="-1">Configurable Modes <a class="header-anchor" href="#configurable-modes" aria-label="Permalink to &quot;Configurable Modes&quot;">​</a></h2><p>The Approval Queue supports two modes of operation:</p><h3 id="auto-approve-mode" tabindex="-1">Auto-Approve Mode <a class="header-anchor" href="#auto-approve-mode" aria-label="Permalink to &quot;Auto-Approve Mode&quot;">​</a></h3><p>In this mode, changes made by the AI Agent are applied immediately without requiring manual review. This is suitable for trusted, routine operations where speed is more important than manual oversight.</p><h3 id="manual-review-mode" tabindex="-1">Manual Review Mode <a class="header-anchor" href="#manual-review-mode" aria-label="Permalink to &quot;Manual Review Mode&quot;">​</a></h3><p>In this mode, all changes made by the AI Agent are held in a pending state until you explicitly approve them. This is the recommended mode when you want to maintain strict control over your product data, especially for bulk operations or content generation.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can switch between auto-approve and manual review modes at any time from the AI Agent configuration settings. Start with manual review to build confidence, then switch to auto-approve for routine tasks once you are comfortable.</p></div><h2 id="reviewing-pending-changes" tabindex="-1">Reviewing Pending Changes <a class="header-anchor" href="#reviewing-pending-changes" aria-label="Permalink to &quot;Reviewing Pending Changes&quot;">​</a></h2><p>When changes are awaiting your review, they appear in the Approval Queue. Each pending change displays:</p><ul><li><strong>The product or entity affected</strong> — Which product, category, or record the change applies to.</li><li><strong>The field being modified</strong> — The specific attribute or field that will be updated.</li><li><strong>The current value</strong> — What the field contains right now.</li><li><strong>The proposed value</strong> — What the AI Agent wants to change it to.</li><li><strong>The timestamp</strong> — When the AI Agent made the change.</li></ul><p>This side-by-side comparison makes it easy to evaluate whether the proposed change is accurate and appropriate.</p><h2 id="approving-changes" tabindex="-1">Approving Changes <a class="header-anchor" href="#approving-changes" aria-label="Permalink to &quot;Approving Changes&quot;">​</a></h2><p>To approve a pending change, review the proposed modification and click the <strong>Approve</strong> button. Once approved, the change is applied to the product data immediately.</p><p>You can also approve multiple changes at once if you are satisfied with a batch of modifications.</p><h2 id="rejecting-changes" tabindex="-1">Rejecting Changes <a class="header-anchor" href="#rejecting-changes" aria-label="Permalink to &quot;Rejecting Changes&quot;">​</a></h2><p>If a proposed change is not suitable, click the <strong>Reject</strong> button. The change is discarded and will not be applied to your data. The AI Agent is not notified of the rejection, so you can reject freely without affecting future AI behavior.</p><h2 id="when-confirmation-is-required" tabindex="-1">When Confirmation is Required <a class="header-anchor" href="#when-confirmation-is-required" aria-label="Permalink to &quot;When Confirmation is Required&quot;">​</a></h2><p>Certain types of changes require additional confirmation, even in auto-approve mode. These include:</p><ul><li><strong>Image changes between requests</strong> — If the AI Agent proposes modifications to product images or media assets, you will be prompted to confirm the change regardless of your approval mode setting.</li><li><strong>Bulk modifications</strong> — Large-scale changes affecting many products may trigger a confirmation step to prevent accidental mass updates.</li><li><strong>Destructive operations</strong> — Any operation that removes or overwrites significant amounts of data will ask for your explicit confirmation.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The Approval Queue is particularly useful when using auto-enrichment features. You can let the AI Agent generate descriptions and SEO content, then review everything in the queue before publishing the changes to your catalog.</p></div>',24)])])}const g=a(n,[["render",r]]);export{d as __pageData,g as default};
